export const fixtures={"parcial": "", "complementar": "", "correto": ""};
export function fixtureBytes(base64,run){
 const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));
 // A proper ancillary PNG text chunk gives each run a distinct, valid file.
 const text=new TextEncoder().encode('validation\0'+run),chunk=new Uint8Array(text.length+12);
 const view=new DataView(chunk.buffer);view.setUint32(0,text.length);
 chunk.set(new TextEncoder().encode('tEXt'),4);chunk.set(text,8);
 let crc=0xffffffff;for(const b of chunk.subarray(4,-4)){crc^=b;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}
 view.setUint32(chunk.length-4,(crc^0xffffffff)>>>0);
 const out=new Uint8Array(bytes.length+chunk.length);
 out.set(bytes.subarray(0,-12));out.set(chunk,bytes.length-12);out.set(bytes.subarray(-12),bytes.length-12+chunk.length);
 return out;
}
